@import url("https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&display=swap");

@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --color-brand-orange: #F97316;
  --color-brand-orange-strong: #FF5A00;
  --color-brand-orange-dark: #C2410C;
  --color-brand-orange-soft: #FFF7ED;
  --color-shell-dark: #07111F;
  --color-shell-dark-soft: #0F172A;
  --color-shell-dark-muted: #1E293B;
  --color-shell-text: #F8FAFC;
  --color-shell-text-muted: #CBD5E1;
  --color-workspace: #F8FAFC;
  --color-workspace-panel: #F1F5F9;
  --color-workspace-gradient-end: #EEF3F8;
  --color-topbar: rgba(255, 255, 255, 0.94);
  --color-card: #FFFFFF;
  --color-surface-muted: rgba(255, 255, 255, 0.96);
  --color-border: #E2E8F0;
  --color-border-strong: #CBD5E1;
  --border-card: rgba(203, 213, 225, 0.92);
  --border-card-strong: rgba(203, 213, 225, 0.96);
  --color-text-main: #0F172A;
  --color-text-muted: #64748B;
  --color-status-green: #16A34A;
  --color-status-blue: #2563EB;
  --color-status-amber: #F59E0B;
  --color-status-red: #DC2626;
  --shadow-card: 0 18px 45px -36px rgba(7, 17, 31, 0.5);
  --shadow-card-strong: 0 18px 44px -36px rgba(7, 17, 31, 0.58);
  --shadow-panel: 0 24px 54px -38px rgba(7, 17, 31, 0.56);
  --shadow-drawer: 0 28px 68px -42px rgba(7, 17, 31, 0.7);
  --shadow-shell: 8px 0 34px -28px rgba(15, 23, 42, 0.72);
  --shadow-topbar: 0 18px 48px -44px rgba(7, 17, 31, 0.62);
  --radius-compact: 0.5rem;
  --radius-card: 0.75rem;
  --radius-panel: 0.875rem;
  --radius-control: 0.625rem;
  --layout-sidebar-width: 17rem;
  --layout-topbar-height: 4.5rem;
  --co-mobile-bottom-nav-height: 5.75rem;
  --co-mobile-bottom-nav-clearance: calc(var(--co-mobile-bottom-nav-height) + env(safe-area-inset-bottom, 0px) + 1.35rem);
  color: var(--color-text-main);
  background:
    radial-gradient(circle at top right, rgba(253, 186, 116, 0.34), transparent 30%),
    linear-gradient(180deg, var(--color-workspace) 0%, var(--color-workspace-gradient-end) 100%);
  font-family: "IBM Plex Sans", "Segoe UI", sans-serif;
}

html {
  scroll-behavior: smooth;
  max-width: 100%;
  overflow-x: clip;
}

body {
  margin: 0;
  min-height: 100vh;
  max-width: 100%;
  overflow-x: clip;
}

button,
input,
select,
textarea {
  font: inherit;
}

#root {
  min-height: 100vh;
  max-width: 100%;
  overflow-x: clip;
}

@layer components {
  .co-brand-intro-screen {
    display: grid;
    min-height: 100vh;
    place-items: center;
    overflow: hidden;
    background:
      radial-gradient(circle at 50% 28%, rgba(249, 115, 22, 0.2), transparent 26rem),
      linear-gradient(180deg, #0f172a, #07111f);
    padding: 1.5rem;
  }

  .co-brand-intro-logo {
    display: block;
    width: min(46rem, 92vw);
    max-height: 72vh;
    border-radius: 1rem;
    object-fit: contain;
    box-shadow: 0 34px 90px -54px rgba(0, 0, 0, 0.98);
  }

  .co-brand-intro-screen .co-splash-progress {
    position: fixed;
    bottom: clamp(2rem, 6vh, 4rem);
  }

  .co-splash-screen {
    position: relative;
    display: grid;
    min-height: 100vh;
    place-items: center;
    overflow: hidden;
    background:
      radial-gradient(circle at 50% 34%, rgba(249, 115, 22, 0.18), transparent 18rem),
      linear-gradient(180deg, rgba(7, 17, 31, 0.94), rgba(7, 17, 31, 0.99));
    padding: 1.5rem;
    color: #f8fafc;
  }

  .co-splash-backdrop {
    position: absolute;
    inset: 0;
    opacity: 0.42;
  }

  .co-splash-backdrop::after {
    position: absolute;
    inset: 0;
    content: "";
    background:
      linear-gradient(90deg, rgba(7, 17, 31, 0.98), rgba(7, 17, 31, 0.28), rgba(7, 17, 31, 0.98)),
      linear-gradient(180deg, rgba(7, 17, 31, 0.22), rgba(7, 17, 31, 0.98));
  }

  .co-splash-backdrop img {
    height: 100%;
    width: 100%;
    object-fit: cover;
    object-position: center top;
  }

  .co-splash-card {
    position: relative;
    z-index: 1;
    display: grid;
    width: min(20rem, 100%);
    justify-items: center;
    border: 1px solid rgba(255, 247, 237, 0.12);
    border-radius: 1.35rem;
    background: rgba(15, 23, 42, 0.74);
    padding: clamp(1.25rem, 4vw, 2rem);
    text-align: center;
    box-shadow: 0 28px 70px -42px rgba(0, 0, 0, 0.9);
    backdrop-filter: blur(16px) saturate(1.12);
  }

  .co-splash-logo {
    display: block;
    width: min(28rem, 86vw);
    max-height: 18rem;
    border-radius: 1rem;
    object-fit: contain;
    box-shadow: 0 24px 54px -44px rgba(249, 115, 22, 0.74);
  }

  .co-splash-icon {
    display: block;
    height: 7.25rem;
    width: 7.25rem;
    border-radius: 1.65rem;
    object-fit: cover;
    box-shadow:
      0 24px 50px -34px rgba(0, 0, 0, 0.95),
      0 18px 42px -32px rgba(249, 115, 22, 0.8);
  }

  .co-splash-progress {
    margin-top: 1.35rem;
    height: 0.28rem;
    width: min(18rem, 72vw);
    overflow: hidden;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.16);
  }

  .co-splash-progress span {
    display: block;
    height: 100%;
    width: 42%;
    border-radius: inherit;
    background: linear-gradient(90deg, #f97316, #ff5a00, #fed7aa);
    animation: co-splash-progress 1.1s ease-in-out infinite;
  }

  .co-splash-label {
    margin-top: 1rem;
    color: #f8fafc;
    font-size: 0.98rem;
    font-weight: 950;
    letter-spacing: 0.02em;
  }

  .co-splash-copy {
    margin-top: 0.3rem;
    color: rgba(226, 232, 240, 0.76);
    font-size: 0.85rem;
    font-weight: 700;
  }

  @keyframes co-splash-progress {
    0% {
      transform: translateX(-120%);
    }
    100% {
      transform: translateX(260%);
    }
  }

  .co-login-screen {
    position: relative;
    display: grid;
    min-height: 100vh;
    place-items: center;
    overflow: hidden;
    background:
      linear-gradient(90deg, rgba(7, 17, 31, 0.82), rgba(7, 17, 31, 0.44), rgba(7, 17, 31, 0.92)),
      linear-gradient(180deg, rgba(7, 17, 31, 0.26), rgba(7, 17, 31, 0.98)),
      url("/brand/apex-login-logo.png") center top / cover no-repeat,
      linear-gradient(135deg, rgba(7, 17, 31, 0.98), rgba(15, 23, 42, 0.98) 48%, rgba(7, 17, 31, 1));
    padding: clamp(1rem, 2.8vw, 2.5rem);
  }

  .co-login-screen::before {
    position: absolute;
    inset: 0;
    content: "";
    background:
      linear-gradient(90deg, rgba(249, 115, 22, 0.1), transparent 26%, rgba(255, 255, 255, 0.04)),
      linear-gradient(180deg, rgba(255, 255, 255, 0.04), transparent 38%);
    pointer-events: none;
  }

  .co-login-shell {
    position: relative;
    z-index: 1;
    display: grid;
    width: min(74rem, 100%);
    min-height: min(43rem, calc(100vh - 3rem));
    grid-template-columns: minmax(0, 1.08fr) minmax(23rem, 0.82fr);
    overflow: hidden;
    border: 1px solid rgba(255, 247, 237, 0.12);
    border-radius: 1.5rem;
    background: rgba(15, 23, 42, 0.7);
    box-shadow: 0 34px 90px -54px rgba(0, 0, 0, 0.92);
  }

  .co-login-hero {
    position: relative;
    min-height: 34rem;
    overflow: hidden;
    background: #07111f;
  }

  .co-login-hero::before {
    display: none;
  }

  .co-login-hero-art,
  .co-login-hero-shade {
    position: absolute;
    inset: 0;
  }

  .co-login-hero-art {
    box-sizing: border-box;
    height: 100%;
    width: 100%;
    object-fit: cover;
    object-position: center center;
    opacity: 0.62;
    transform: scale(1.02);
  }

  .co-login-hero-shade {
    background:
      linear-gradient(180deg, rgba(7, 17, 31, 0.2), rgba(7, 17, 31, 0.52) 38%, rgba(7, 17, 31, 0.96)),
      linear-gradient(90deg, rgba(7, 17, 31, 0.78), rgba(7, 17, 31, 0.24) 48%, rgba(7, 17, 31, 0.68));
  }

  .co-login-hero-emblem {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
    padding: 2rem;
  }

  .co-login-hero-emblem img {
    width: min(21rem, 66%);
    height: auto;
    border-radius: 2.7rem;
    box-shadow:
      0 34px 88px -48px rgba(0, 0, 0, 0.96),
      0 20px 54px -42px rgba(249, 115, 22, 0.94);
  }

  .co-login-hero-copy {
    position: relative;
    z-index: 1;
    display: flex;
    min-height: 100%;
    flex-direction: column;
    justify-content: flex-end;
    padding: clamp(1.35rem, 3.2vw, 2.65rem);
    color: #f8fafc;
  }

  .co-login-hero-kicker {
    display: flex;
    width: fit-content;
    max-width: 100%;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.48rem;
    border: 1px solid rgba(255, 247, 237, 0.18);
    border-radius: 999px;
    background: rgba(7, 17, 31, 0.58);
    padding: 0.42rem 0.52rem;
    box-shadow: 0 18px 42px -34px rgba(0, 0, 0, 0.86);
    backdrop-filter: blur(12px);
  }

  .co-login-hero-kicker span,
  .co-login-hero-kicker strong {
    display: block;
    overflow-wrap: anywhere;
    font-size: 0.66rem;
    font-weight: 950;
    letter-spacing: 0.12em;
    line-height: 1;
    text-transform: uppercase;
  }

  .co-login-hero-kicker span {
    color: #fdba74;
  }

  .co-login-hero-kicker strong {
    border-radius: 999px;
    background: rgba(34, 197, 94, 0.16);
    color: #bbf7d0;
    padding: 0.36rem 0.48rem;
  }

  .co-login-hero-copy h1 {
    margin-top: 1rem;
    max-width: 34rem;
    color: #ffffff;
    font-size: clamp(3.1rem, 5.4vw, 4.7rem);
    font-weight: 950;
    letter-spacing: 0;
    line-height: 0.94;
    text-transform: uppercase;
    text-shadow: 0 18px 34px rgba(0, 0, 0, 0.55);
  }

  .co-login-hero-copy p {
    margin-top: 1.1rem;
    max-width: 34rem;
    color: rgba(226, 232, 240, 0.86);
    font-size: 1.06rem;
    font-weight: 750;
    line-height: 1.55;
  }

  .co-login-workflow-strip {
    display: flex;
    margin-top: 0.85rem;
    flex-wrap: wrap;
    gap: 0.42rem;
  }

  .co-login-workflow-strip span {
    position: relative;
    display: block;
    border: 1px solid rgba(255, 247, 237, 0.14);
    border-radius: 999px;
    background: rgba(7, 17, 31, 0.62);
    color: rgba(248, 250, 252, 0.92);
    font-size: 0.72rem;
    font-weight: 900;
    line-height: 1;
    padding: 0.48rem 0.62rem;
    backdrop-filter: blur(12px);
  }

  .co-login-hero-metrics {
    display: grid;
    margin-top: 1.5rem;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.75rem;
  }

  .co-login-hero-metrics div {
    min-width: 0;
    border: 1px solid rgba(255, 247, 237, 0.14);
    border-radius: 0.9rem;
    background: rgba(7, 17, 31, 0.58);
    padding: 0.85rem;
    backdrop-filter: blur(12px);
  }

  .co-login-hero-metrics span {
    display: block;
    color: #fdba74;
    font-size: 0.64rem;
    font-weight: 950;
    letter-spacing: 0.16em;
    text-transform: uppercase;
  }

  .co-login-hero-metrics strong {
    display: block;
    margin-top: 0.35rem;
    overflow-wrap: anywhere;
    color: #f8fafc;
    font-size: 0.88rem;
    line-height: 1.2;
  }

  .co-login-panel {
    display: flex;
    min-width: 0;
    flex-direction: column;
    justify-content: center;
    border-left: 1px solid rgba(249, 115, 22, 0.24);
    background:
      radial-gradient(circle at top right, rgba(249, 115, 22, 0.18), transparent 18rem),
      linear-gradient(180deg, rgba(15, 23, 42, 0.98), rgba(7, 17, 31, 0.99));
    padding: clamp(1.15rem, 2.7vw, 2rem);
  }

  .co-login-panel-head {
    display: flex;
    min-width: 0;
    align-items: center;
    gap: 0.9rem;
  }

  .co-login-icon-tile {
    display: grid;
    height: 3.25rem;
    width: 3.25rem;
    flex-shrink: 0;
    place-items: center;
    overflow: hidden;
    border: 1px solid rgba(255, 247, 237, 0.16);
    border-radius: 0.9rem;
    background: #07111f;
    box-shadow: 0 18px 34px -26px rgba(249, 115, 22, 0.58);
  }

  .co-login-icon-tile img,
  .co-brand-mark-image,
  .co-mobile-brand-mark-image {
    height: 100%;
    width: 100%;
    object-fit: cover;
  }

  .co-login-wordmark {
    display: block;
    width: min(14.5rem, 100%);
    height: auto;
    border-radius: 0.35rem;
  }

  .co-login-wordmark-transparent {
    display: block;
    width: min(10.5rem, 100%);
    height: auto;
    object-fit: contain;
    object-position: left center;
  }

  .co-login-panel-head p,
  .co-login-form-intro span,
  .co-login-support-grid span,
  .co-login-demo-card small {
    color: rgba(203, 213, 225, 0.88);
    font-size: 0.88rem;
    font-weight: 700;
    line-height: 1.45;
  }

  .co-login-brand-title {
    color: #f8fafc !important;
    font-size: 1.2rem !important;
    font-weight: 950 !important;
    letter-spacing: 0;
    line-height: 1 !important;
    text-transform: uppercase;
  }

  .co-login-status-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.9rem;
    margin-top: 1.1rem;
    border: 1px solid rgba(249, 115, 22, 0.44);
    border-radius: 0.95rem;
    background: rgba(249, 115, 22, 0.1);
    padding: 0.85rem 0.95rem;
    color: #fed7aa;
    font-size: 0.84rem;
    font-weight: 800;
    line-height: 1.35;
  }

  .co-login-status-meta {
    display: grid;
    flex: 0 0 auto;
    justify-items: end;
    gap: 0.25rem;
  }

  .co-login-status-meta small {
    color: #fdba74;
    font-size: 0.64rem;
    font-weight: 950;
    letter-spacing: 0.08em;
    line-height: 1;
    text-align: right;
    text-transform: uppercase;
  }

  .co-login-form-intro {
    margin-top: 1.15rem;
  }

  .co-login-form-intro p,
  .co-login-support-grid p,
  .co-login-demo-card p {
    color: #f8fafc;
    font-size: 1rem;
    font-weight: 950;
    line-height: 1.1;
  }

  .co-login-form-intro span {
    display: block;
    margin-top: 0.35rem;
  }

  .co-login-signup-brief {
    display: grid;
    gap: 0.75rem;
    margin-top: 1rem;
    border: 1px solid rgba(249, 115, 22, 0.32);
    border-radius: 1rem;
    background:
      linear-gradient(135deg, rgba(249, 115, 22, 0.16), rgba(15, 23, 42, 0.66)),
      rgba(7, 17, 31, 0.72);
    padding: 0.95rem;
    box-shadow: 0 18px 40px -34px rgba(0, 0, 0, 0.88);
  }

  .co-login-signup-brief-head {
    display: grid;
    min-width: 0;
    gap: 0.42rem;
  }

  .co-login-signup-badge {
    display: inline-flex;
    width: fit-content;
    max-width: 100%;
    align-items: center;
    border: 1px solid rgba(253, 186, 116, 0.38);
    border-radius: 999px;
    background: rgba(249, 115, 22, 0.16);
    padding: 0.18rem 0.62rem;
    color: #fed7aa;
    font-size: 0.68rem;
    font-weight: 950;
    letter-spacing: 0.08em;
    line-height: 1.15;
    text-transform: uppercase;
  }

  .co-login-signup-brief-head strong {
    overflow-wrap: anywhere;
    color: #f8fafc;
    font-size: 0.96rem;
    font-weight: 950;
    line-height: 1.25;
  }

  .co-login-signup-brief-head span,
  .co-login-field-help {
    color: rgba(203, 213, 225, 0.88);
    font-size: 0.78rem;
    font-weight: 800;
    line-height: 1.45;
  }

  .co-login-signup-steps {
    display: grid;
    gap: 0.5rem;
  }

  .co-login-signup-steps div {
    display: grid;
    min-width: 0;
    grid-template-columns: 1.65rem minmax(0, 1fr);
    gap: 0.6rem;
    align-items: start;
    border: 1px solid rgba(255, 247, 237, 0.12);
    border-radius: 0.82rem;
    background: rgba(255, 255, 255, 0.055);
    padding: 0.66rem;
  }

  .co-login-signup-steps small {
    display: grid;
    height: 1.65rem;
    width: 1.65rem;
    place-items: center;
    border: 1px solid rgba(249, 115, 22, 0.34);
    border-radius: 999px;
    background: rgba(249, 115, 22, 0.14);
    color: #fdba74;
    font-size: 0.72rem;
    font-weight: 950;
    line-height: 1;
  }

  .co-login-signup-steps span {
    display: grid;
    min-width: 0;
    gap: 0.2rem;
  }

  .co-login-signup-steps strong {
    color: #f8fafc;
    font-size: 0.8rem;
    font-weight: 950;
    line-height: 1.15;
  }

  .co-login-signup-steps em {
    overflow-wrap: anywhere;
    color: rgba(203, 213, 225, 0.84);
    font-size: 0.72rem;
    font-style: normal;
    font-weight: 800;
    line-height: 1.35;
  }

  .co-login-form {
    display: grid;
    gap: 0.9rem;
    margin-top: 1.05rem;
  }

  .co-login-field-help {
    margin-top: -0.42rem;
  }

  .co-login-submit {
    min-height: 2.9rem;
    width: 100%;
  }

  .co-login-support-grid {
    display: grid;
    gap: 0.65rem;
    margin-top: 0.85rem;
  }

  .co-login-quick-tabs {
    display: grid;
    align-self: flex-end;
    width: min(100%, 27rem);
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.55rem;
    margin-top: 1rem;
  }

  .co-login-quick-tabs div {
    min-width: 0;
    border: 1px solid rgba(255, 247, 237, 0.12);
    border-radius: 0.8rem;
    background: rgba(7, 17, 31, 0.48);
    padding: 0.68rem;
  }

  .co-login-quick-tabs span {
    display: block;
    color: #fdba74;
    font-size: 0.58rem;
    font-weight: 950;
    letter-spacing: 0.16em;
    line-height: 1;
    text-transform: uppercase;
  }

  .co-login-quick-tabs strong {
    display: block;
    margin-top: 0.35rem;
    overflow-wrap: anywhere;
    color: #f8fafc;
    font-size: 0.72rem;
    line-height: 1.15;
  }

  .co-login-support-grid > div,
  .co-login-demo-card {
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 0.95rem;
    background: rgba(255, 255, 255, 0.055);
    padding: 0.95rem;
    box-shadow: 0 18px 40px -34px rgba(0, 0, 0, 0.88);
  }

  .co-login-support-grid span,
  .co-login-demo-card span {
    display: block;
    margin-top: 0.35rem;
  }

  .co-login-demo-card {
    display: grid;
    gap: 0.42rem;
    margin-top: 0.65rem;
    background:
      linear-gradient(135deg, rgba(249, 115, 22, 0.1), transparent 42%),
      rgba(15, 23, 42, 0.78);
  }

  .co-login-demo-card-head {
    display: flex;
    min-width: 0;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.75rem;
  }

  .co-login-demo-card-head > div {
    min-width: 0;
  }

  .co-login-demo-card-head > div > span {
    color: rgba(203, 213, 225, 0.9);
    font-size: 0.88rem;
    font-weight: 700;
    line-height: 1.45;
  }

  .co-login-demo-card-head > span {
    flex-shrink: 0;
    white-space: nowrap;
  }

  .co-login-demo-actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.55rem;
    margin-top: 0.55rem;
  }

  .co-login-demo-preset {
    display: grid;
    min-width: 0;
    gap: 0.32rem;
    border: 1px solid rgba(249, 115, 22, 0.32);
    border-radius: 0.82rem;
    background: rgba(7, 17, 31, 0.72);
    padding: 0.7rem;
    color: #f8fafc;
    text-align: left;
    box-shadow: 0 14px 28px -24px rgba(249, 115, 22, 0.72);
    transition: border-color 150ms ease, transform 150ms ease, background 150ms ease;
  }

  .co-login-demo-preset:first-child {
    border-color: rgba(249, 115, 22, 0.62);
    background:
      linear-gradient(135deg, rgba(249, 115, 22, 0.2), transparent 68%),
      rgba(7, 17, 31, 0.78);
  }

